async function assertDisplayedMessage(aboutMessage, expected) {
  const messagePaneBrowser = aboutMessage.getMessagePaneBrowser();
  const mailboxURL = expected.folder.getUriForMsg(expected);
  const messageURI = mailboxService.getUrlForUri(mailboxURL);
  if (messagePaneBrowser.currentURI.spec != messageURI.spec) {
    await BrowserTestUtils.browserLoaded(
      messagePaneBrowser,
      undefined,
      messageURI.spec
    );
  }

  Assert.equal(
    aboutMessage.gMessage.messageId,
    expected.messageId,
    "correct message loaded"
  );
  Assert.equal(
    messagePaneBrowser.currentURI.spec,
    messageURI.spec,
    "correct message displayed"
  );
}

async function assertDisplayedThread(firstMessage) {
  const items = multiMessageBrowser.contentDocument.querySelectorAll("li");
  Assert.equal(
    items[0].dataset.messageId,
    firstMessage.messageId,
    "correct thread displayed"
  );
  Assert.ok(
    BrowserTestUtils.isVisible(multiMessageBrowser),
    "multimessageview visible"
  );
}

async function assertNoDisplayedMessage(aboutMessage) {
  const messagePaneBrowser = aboutMessage.getMessagePaneBrowser();
  if (messagePaneBrowser.currentURI.spec != "about:blank") {
    await BrowserTestUtils.browserLoaded(
      messagePaneBrowser,
      undefined,
      "about:blank"
    );
  }

  Assert.equal(aboutMessage.gMessage, null, "no message loaded");
  Assert.equal(
    messagePaneBrowser.currentURI.spec,
    "about:blank",
    "no message displayed"
  );
